let current=null,items=[],templates=[],selectedTemplate=0,totalItems=0,selectedIndex=-1;
let categories=[],seriesV=[],selectedCatCode='',selectedV='V06',autoS=null,selectedDur='30s',selectedMode='showcase';
const PAGE=100;
let searchTimer=null;
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const directImageUrl=u=>String(u||'').replace('co.th../','co.th/');
const imageUrl=u=>{const d=directImageUrl(u);return d?('/api/wdi/image?url='+encodeURIComponent(d)):'';};
async function loadDataStatus(){try{const d=await fetch('/api/data-status').then(r=>r.json());const el=$('dataSource');if(!el)return;const good=d.files?.find(x=>x.name==='Product Sheet'&&x.available);const fit=d.files?.find(x=>x.name==='Fitment Master'&&x.available);el.classList.toggle('safe',!!good&&!!fit);el.innerHTML=`<i></i> Local DB ${d.products||0} · Fitment ${d.fitmentRows||0} · ${good&&fit?'พร้อมทำงานแม้ WDI ล่ม':'ใช้ Cache สำรอง'}`;}catch{const el=$('dataSource');if(el)el.innerHTML='<i></i> Local DB';}}
async function boot(){try{await loadDataStatus();const [m,t,cats,vv]=await Promise.all([fetch('/api/meta').then(r=>r.json()),fetch('/api/templates').then(r=>r.json()),fetch('/api/categories').then(r=>r.json()).catch(()=>[]),fetch('/api/series-v').then(r=>r.json()).catch(()=>[])]);categories=cats;seriesV=vv;renderVChips();
$('category').innerHTML='<option value="">ทุกหมวดหมู่</option>'+m.categories.map(x=>`<option>${esc(x)}</option>`).join('');
if(m.brands&&m.brands.length){$('brand').innerHTML='<option value="">ทุกยี่ห้อรถ</option>'+m.brands.map(x=>`<option>${esc(x)}</option>`).join('');}else{$('brand').style.display='none';}
if(m.models&&m.models.length){$('model').innerHTML='<option value="">ทุกรุ่นรถ</option>'+m.models.map(x=>`<option>${esc(x)}</option>`).join('');}else{$('model').style.display='none';}
templates=t;const tc=$('templateCount');if(tc)tc.textContent=`${t.length} แบบ`;renderTemplates();updateResolvePreview();
$('search').addEventListener('input',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>loadProducts(),350);});
await loadProducts();loadDashboard();renderStatusChips();renderQprompts();renderDur();loadFlowModels();const h=await fetch('/api/health').then(r=>r.json());$('health').textContent='● Online';$('health').title=`${h.products} products · ${h.templates} series · ${h.ai?.model||'AI'}`;const sys=`MODEL ${esc(h.ai?.model||'-')}<br>PRODUCTS ${h.products} · SERIES ${h.templates}<br>DB ${(h.tracking||{}).backend||'-'} · ${esc((h.tracking||{}).db||'')}`;if($('systemDrop'))$('systemDrop').innerHTML=sys;if($('sysDiag'))$('sysDiag').innerHTML='System · '+esc(h.ai?.model||'-')+' · DB '+((h.tracking||{}).backend||'-');}catch(e){$('health').textContent='● เชื่อมต่อไม่ได้'}}
function productLabel(x){return `<span class="code">${esc(x['Product Code']||'-')}</span><span>${esc(x['Product Name (TH)']||x['Product Name (EN)']||'-')}</span><small>${esc(x.Category||x['Context Path']||'')}</small><span class="vprog" data-vp="${esc(x['Product Code']||'')}">○ ยังไม่เริ่มแนวคลิป</span>`;}
function renderProductList(){
  $('count').textContent=`แสดง ${items.length} จาก ${totalItems} รายการ`;
  let html=items.map((x,i)=>`<button class="item${i===selectedIndex?' active':''}" onclick="selectProduct(${i},this)">${productLabel(x)}</button>`).join('')||'<div class="empty small">ไม่พบสินค้า</div>';
  if(items.length<totalItems) html+=`<button class="item load-more" onclick="loadMore()">แสดงเพิ่ม (${totalItems-items.length} เหลือ) ↓</button>`;
  $('products').innerHTML=html;const pl=$('products');if(pl)pl.classList.toggle('anim-list',items.length<=40);paintBadges();
}
async function loadProducts(){selectedIndex=-1;const sf=$('statusFilter')?.value||'';const p=new URLSearchParams({q:$('search').value,category:$('category').value,brand:$('brand').value,model:$('model').value,limit:sf?1200:PAGE,offset:0});const d=await fetch('/api/products?'+p).then(r=>r.json());let list=Array.isArray(d)?d:(d.products||[]);if(sf){try{const m=await fetch('/api/jobs/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({codes:list.map(x=>x['Product Code']).filter(Boolean)})}).then(r=>r.json());statusMap={...statusMap,...m};const g=STATUS_GROUPS[sf]||[];list=list.filter(x=>g.includes(((m[x['Product Code']]||{}).state||'NOT_STARTED')));}catch{}totalItems=list.length;items=list.slice(0,300);}else{totalItems=Array.isArray(d)?list.length:(d.total||list.length);items=list;}renderStatusChips();renderProductList();}
async function loadMore(){const p=new URLSearchParams({q:$('search').value,category:$('category').value,brand:$('brand').value,model:$('model').value,limit:PAGE,offset:items.length});const d=await fetch('/api/products?'+p).then(r=>r.json());const list=Array.isArray(d)?d:(d.products||[]);if(Array.isArray(d))totalItems=items.length+list.length;else totalItems=d.total||totalItems;items=items.concat(list);renderProductList();}
async function syncWdi(){showToast('กำลัง Sync WDI...');try{const r=await fetch('/api/wdi/sync',{method:'POST'}),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'sync failed');showToast(`Sync WDI สำเร็จ ${d.total} สินค้า ✓`);await loadProducts()}catch(e){showToast(e.message||'Sync ไม่สำเร็จ',false)}}
function marketplaceFacts(p){const fitBrands=p['Fitment Brands']||'';const fitModels=p['Fitment Models']||'';const fitContexts=p['Fitment Contexts']||'';const evidence=p['Fitment Evidence']||'';return {code:p['Product Code']||'',nameTH:p['Product Name (TH)']||'',nameEN:p['Product Name (EN)']||'',category:p.Category||'',subCategory:p['Sub Category']||'',descriptionTH:p['Description (TH)']||'',descriptionEN:p['Description (EN)']||'',fitmentBrands:fitBrands,fitmentModels:fitModels,fitmentContexts:fitContexts,fitmentEvidence:evidence,sourceUrl:p['Product URL']||'',mainImage:p['Main Image URL']||'',additionalImages:p['Additional Images']||''};}
function buildLocalMarketplace(p){const f=marketplaceFacts(p);const lock='Use the supplied WDI/DIAMOND product reference as the visual source of truth. Preserve exact silhouette, proportions, lens, housing, bezel, reflector, connector, wire count, mounting points, screws/clips, materials, colors, finish and visible markings. Do not redesign, beautify, mirror, recolor, merge variants, add unseen components, or invent technical features. Never infer fitment from appearance.';const brand='BRAND IDENTITY: DIAMOND / ไฟตราเพชร. Use the supplied DIAMOND logo asset exactly; do not redraw, distort, recolor, replace or invent a logo.';const fit=f.fitmentModels||f.fitmentBrands||f.fitmentContexts?'VERIFIED WDI FITMENT NAVIGATION: '+[f.fitmentBrands,f.fitmentModels,f.fitmentContexts].filter(Boolean).join(' | '):'NO VERIFIED FITMENT PROVIDED: do not show a vehicle or compatibility claim.';const base='Create a premium high-end automotive aftermarket product advertisement for WDI / DIAMOND. '+brand+' '+fit+' PRODUCT: '+JSON.stringify(f)+' '+lock;const negative='wrong product, changed geometry, wrong lens, wrong connector, wrong wire count, invented fitment, random vehicle, merged variants, extra parts, fake logo, fake Thai text, misspelled product code, fake specifications, price, phone, QR, watermark, deformation, duplicate product, cartoon, surreal, excessive VFX';return {prompts:{hero:base+' HERO 4:5: luxury automotive advertising, product-dominant composition, premium midnight navy background, electric blue rim light, metallic silver and gold accents, cinematic three-point lighting, realistic reflections, clean negative space for text added later.',detail:base+' DETAIL 1:1: macro catalog photography, 3-4 visual detail zones for only visible components such as lens, housing, connector, reflector, mounting points; technical callout lines may be added in post-production, no invented details.',context:base+' CONTEXT 4:5: show the product in a realistic automotive environment; show a vehicle ONLY when verified WDI fitment is present, and use only the verified brand/model/year context; otherwise use a neutral premium workshop with no vehicle compatibility claim.',catalog:base+' CATALOG 4:5: product hero on one side, structured navy/gold information-panel space on the other, premium automotive catalog design, leave all critical text for post-production.',social:base+' SOCIAL / MARKETPLACE 4:5: immediate product recognition, strong hero product, clean premium DIAMOND visual identity, restrained blue/gold accents, mobile-first hierarchy, leave readable text areas for post-production.'},negative_prompt:negative,brand_rules:'DIAMOND / ไฟตราเพชร visual identity: midnight navy, electric blue, metallic silver, diamond yellow/gold, premium automotive advertising; exact logo asset only.',source_facts:[f.code,f.nameTH,f.category,f.subCategory,f.fitmentModels,f.fitmentContexts].filter(Boolean).join(' | ')};}
function downloadMarketplacePrompts(){if(!window.lastMarketplace)return;const names=[['hero','Hero 4:5'],['detail','Detail 1:1'],['context','Context 4:5'],['catalog','Catalog 4:5'],['social','Social 4:5']];const text=names.map(([k,l])=>'### '+l+'\n'+(window.lastMarketplace.prompts?.[k]||'')).join('\n\n')+'\n\n### Negative Prompt\n'+(window.lastMarketplace.negative_prompt||'')+'\n\n### Source Facts\n'+(window.lastMarketplace.source_facts||'');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));a.download='DIAMOND-'+(current?.['Product Code']||'Marketplace-Prompts')+'-Pro.txt';a.click();URL.revokeObjectURL(a.href);showToast('ดาวน์โหลด Prompt Pack แล้ว ✓');}

async function enhanceMarketplace(btn){if(!current)return;const t0=Date.now();if(btn){btn.disabled=true;btn.textContent='AI กำลังปรับ...';}try{const r=await fetch('/api/generate-marketplace',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product:current})});const d=await r.json();if(d.error||d.raw)throw new Error(d.error||'AI คืนรูปไม่ครบ');window.lastMarketplace=d;generateMarketplaceRenderAI(d,Math.round((Date.now()-t0)/1000));}catch(e){showToast('AI Enhance ไม่สำเร็จ: '+e.message+' — ใช้เวอร์ชัน template ได้เลย',false);}finally{if(btn){btn.disabled=false;btn.textContent='AI Enhance';}}}
function generateMarketplaceRenderAI(d,secs){const names=[['hero','Hero 4:5'],['detail','Detail 1:1'],['context','Context'],['catalog','Catalog'],['social','Social']];window.lastMarketplace=d;const o=$('output');o.innerHTML=`<section class="result"><div class="result-head"><div><h2>Marketplace Prompts (AI)</h2><small class="result-sub">AI ปรับแล้วใน ${secs}วิ</small></div></div>`+names.map(([k,l])=>`<div class="box"><div class="box-title"><h3>${l}</h3><button onclick="copyText(window.lastMarketplace.prompts['${k}'],this)">Copy</button></div><div class="out">${esc((d.prompts||{})[k]||'')}</div></div>`).join('')+`</section>`;}
function workflowPanel(){return `<section class="workflow-card"><div class="workflow-head"><div><b>🎬 ขั้นตอนทำวิดีโอ</b><small>PDCA แบบย่อ: วางแผน → เจน → ตรวจ → ปรับ</small></div><span class="workflow-badge">READY</span></div><div class="workflow-steps"><div class="wf-step active" data-wf="plan"><strong>1</strong><span>PLAN</span><small>เลือกสินค้า + Series + ตรวจ Source</small></div><div class="wf-step" data-wf="do"><strong>2</strong><span>DO</span><small>สร้าง Prompt → Google Flow</small></div><div class="wf-step" data-wf="check"><strong>3</strong><span>CHECK</span><small>เช็กภาพ / ข้อมูล / ข้อความ</small></div><div class="wf-step" data-wf="act"><strong>4</strong><span>ACT</span><small>แก้ Prompt → เจนใหม่ → Export</small></div></div><div class="workflow-note">💡 <b>หลักสำคัญ:</b> Flow สร้างภาพและ Motion เป็นหลัก · ข้อความไทย/สเปก/CTA ใส่ภายหลัง · ห้ามให้ AI เดาข้อมูลสินค้า</div><div id="guide" class="mini-guide" hidden><b>📘 คู่มือ 60 วินาที</b><ol><li>เลือกสินค้า แล้วตรวจ “ข้อมูลจริงจาก WDI”</li><li>เลือก Series ให้ตรงเป้าหมายของแพลตฟอร์ม</li><li>กด “สร้าง Content Pack + Google Flow”</li><li>Copy Flow Prompt ไป Google Flow และแนบภาพสินค้าจริงเป็น Reference/Ingredients</li><li>เจนแล้วตรวจทรง สี ชิ้นส่วน และความต่อเนื่อง</li><li>ผ่านแล้วใส่ Text/Logo/CTA ในงานตัดต่อ แล้ว Export ตามแพลตฟอร์ม</li></ol><div class="guide-rule">ถ้าผิด → กลับไปแก้ Prompt ไม่ใช่แต่งข้อมูลเพิ่มเอง</div></div></section>`}
function toggleGuide(){const g=document.getElementById('guide');if(g)g.hidden=!g.hidden;}
function setWorkflow(step){document.querySelectorAll('.wf-step').forEach(x=>x.classList.toggle('active',x.dataset.wf===step));const b=document.querySelector('.workflow-badge');if(b)b.textContent=step.toUpperCase();}
function renderPostGenWorkflow(){const o=$('output');if(!o)return;const old=o.querySelector('.postgen-workflow');if(old)old.remove();const wrap=document.createElement('div');wrap.className='postgen-workflow';wrap.innerHTML=`<div class="pg-head"><b>✅ Prompt Pack เสร็จแล้ว — ไปทำต่อใน Google Flow</b><button class="secondary" onclick="setWorkflow('do')">เริ่ม DO</button></div><div class="pg-grid"><div><b>1. Copy Flow</b><span>เลือก Scene → Copy Flow Prompt</span></div><div><b>2. Attach Images</b><span>แนบภาพสินค้าเป็น Reference/Ingredients ตามที่ระบบแนะนำ</span></div><div><b>3. Generate</b><span>ใช้ Omni Flash 360p / 10s / 1 output สำหรับ Preview ก่อน ลดเครดิต</span></div><div><b>4. QC</b><span>ตรวจสินค้า → ข้อมูล → Motion → Text-safe area แล้วค่อยเจน Final</span></div></div><div class="pg-actions"><button class="secondary" onclick="setWorkflow('check')">✓ ตรวจงาน (CHECK)</button><button class="secondary" onclick="setWorkflow('act')">↻ ปรับ/เจนใหม่ (ACT)</button><button class="secondary" onclick="copyText('Flow → QC → Text Overlay → Export → Publish → เก็บผลลัพธ์กลับมาปรับ Series รอบถัดไป',this)">Copy Workflow</button></div>`;o.prepend(wrap);}
function selectProduct(i,btn){current=items[i];window.current=current;window.selectedProductForUx=current;selectedIndex=i;document.querySelectorAll('#products .item').forEach(b=>b.classList.remove('active'));if(btn)btn.classList.add('active');$('detail').innerHTML=`<div class="steps-mini" aria-label="ขั้นตอน"><span class="sm on">01 สินค้า</span><span class="sm">02 Sheet</span><span class="sm">03 แนวคลิป</span><span class="sm">04 สร้าง</span></div><div class="ph-head"><div><div class="eyebrow">${esc(current.Category)} / ${esc(current['Sub Category'])}</div><h1>${esc(current['Product Name (TH)']||'-')}</h1></div><div class="ph-actions"><button class="secondary" onclick="copyProduct()">คัดลอก</button></div></div><div class="hero-grid"><div class="hero-media">${current['Main Image URL']?`<img class="product-img" loading="lazy" src="${esc(imageUrl(current['Main Image URL']))}" data-direct="${esc(directImageUrl(current['Main Image URL']))}" onerror="if(this.dataset.direct&&this.src!==this.dataset.direct){this.src=this.dataset.direct;}else{this.outerHTML='<div class=image-missing>ไม่มีรูปสินค้า</div>';}">`:''}<div class="thumbs">${thumbsHtml(current)}</div></div><div class="hero-info"><div class="code-big">${esc(current['Product Code']||'ไม่มีรหัส')}</div><div class="pills"><span class="pill" id="pillCat">C…</span><span class="pill" id="pillFit">ตรวจ Fitment…</span></div><ul class="keyfacts">${keyFactsHtml(current)}</ul><div class="inforow"><button class="secondary" onclick="openTruth()">ดูข้อมูลทั้งหมด</button></div><details class="facts"><summary>รายละเอียดสินค้า <small style="opacity:.6">แตะเพื่อดูทั้งหมด</small></summary><p>${esc(current['Description (TH)']||'-')}</p><p class="en">${esc(current['Description (EN)']||'')}</p><a target="_blank" href="${esc(current['Product URL']||'#')}">เปิดหน้าสินค้า ↗</a></details></div></div><section class="step sheet-step" aria-label="ขั้นตอนที่ 2 Product Sheet"><div class="step-head"><span class="step-no">2</span><b>Product Sheet</b><small>บัตรประจำตัวสินค้า — AI ทุกตัวใช้ใบเดียวกัน</small></div><div id="sheetBox"><div class="empty-state" style="padding:10px">กำลังสร้าง Product Sheet...</div></div></section><section class="step" aria-label="ขั้นตอนที่ 2 แนวคลิป"><div class="step-head"><span class="step-no">3</span><b>แนวคลิป</b><small>V + หมวด · S จับคู่อัตโนมัติ</small></div><div id="selVBox"></div>${catVRow()}<details id="prodDetails"><summary>⚙ Production Details <span id="pdMap"></span></summary><div id="pdBody"></div><div id="vmatrix"></div><details class="wfwrap"><summary>📌 วิธีทำวิดีโอ (PDCA)</summary>${workflowPanel()}</details></details></section><section class="step" aria-label="ขั้นตอนที่ 3 สร้าง"><div class="step-head"><span class="step-no">4</span><b>สร้าง</b><small>Generate → QC → Publish</small></div><div class="action-zone"><button id="btnGenerate" class="generate" onclick="generate()">✨ สร้าง Content Plan</button><div class="action-row secondary-row"><button class="secondary" onclick="generateMarketplace()">🛒 Marketplace Prompts</button><button class="secondary" onclick="openDistStudio()">📣 โฆษณาทุกแพลตฟอร์ม</button></div><div class="action-row tertiary-row"><button class="secondary" onclick="sheetImageStudio()">🪪 สร้าง Product Sheet Prompt</button></div></div></section><div class="gen-sub" id="genSub"></div><div id="output"></div>`;suggestCategory();trackSelect();loadVMatrix();loadSheetBox()}
function renderTemplates(autoCode){const el=$('templates');if(!el)return;if(!templates.length){el.innerHTML='<div class="empty-state">ยังไม่มี production template</div>';return;}el.innerHTML=templates.map((t,i)=>{const isAuto=t.code===autoCode;return `<div class="template${isAuto?' active':''}" title="${esc(t.useWhen||'')}" style="${isAuto?'':'opacity:.7'}">${isAuto?'<b style="color:#ffd76a">🤖 AUTO · </b>':''}<b>${esc(t.code||('T'+(i+1)))}</b><small>${esc(t.name)}${t.risk?` · ⚠ ${esc(t.risk)}`:''}</small></div>`}).join('')}
let vFilter='';
function renderVChips(){const el=$('vchips');if(!el)return;if(!seriesV.length){el.innerHTML='<div class="empty-state">ยังไม่มีแนวคลิป</div>';return;}const list=seriesV.filter(v=>!vFilter||(v.code+' '+(v.name||'')+' '+(v.when||'')).toLowerCase().includes(vFilter));el.innerHTML=list.map(v=>`<button class="vcard${v.code===selectedV?' on':''}" onclick="setV('${v.code}')" title="${esc(v.when||'')}"><span class="vdur">${esc(v.duration||'')}</span><b>${esc(v.code)} · ${esc(v.name)}</b><small>${esc(v.when||'')}</small></button>`).join('')||'<div class="empty-state">ไม่พบแนวที่ค้นหา</div>'}
function setV(code){selectedV=code;renderVChips();updateResolvePreview();trackSelect();loadVMatrix();closeCreative();showToast(`แนวคลิป ${code}`)}
async function updateResolvePreview(){try{const p=new URLSearchParams({v:selectedV,cat:(($('catCode')||{}).value||selectedCatCode||''),category:current?.Category||'',sub:current?.['Sub Category']||'',th:current?.['Product Name (TH)']||'',en:current?.['Product Name (EN)']||''});const d=await fetch('/api/resolve-series?'+p).then(r=>r.json());autoS=d;renderTemplates(d.sCode);
const sv=(seriesV.find(x=>x.code===d.vCode)||{});
const sb=$('selVBox');if(sb)sb.innerHTML=`<div class="selv"><div><b>${esc(d.vCode)} · ${esc(sv.name||'')}</b><br><small>${esc(selectedDur)} · ${esc(sv.duration||'')}</small></div><button class="secondary" onclick="openCreative()">เปลี่ยนแนวคลิป</button></div>`;
const pm=$('pdMap');if(pm)pm.textContent=`${d.vCode} → ${d.sCode}`;
const pb=$('pdBody');if(pb){const t=(templates.find(x=>x.code===d.sCode)||{});pb.innerHTML=`<b>${esc(d.sCode)} ${esc(d.sName)}</b>${d.sRisk?` · ⚠ ${esc(d.sRisk)}`:''}${d.sUseWhen?`<br><small>ใช้เมื่อ: ${esc(d.sUseWhen)}</small>`:''}${t.required?`<br><small>ข้อมูลบังคับ: ${esc(t.required)}</small>`:''}${t.noGuess?`<br><small>ห้ามเดา: ${esc(t.noGuess)}</small>`:''}`;}const gs=$('genSub');if(gs)gs.textContent=`${d.vCode} · ${selectedDur} · ${selectedFlowModel} → ${d.sCode} · Auto mapped${d.categoryAuto?' · หมวด auto':''}`;}catch{}}
function catVRow(){return `<div class="catrow" style="display:flex;gap:8px;align-items:center;margin:10px 0;flex-wrap:wrap"><label>🏷 หมวด C: <select id="catCode" onchange="selectedCatCode=this.value;const n=document.getElementById('catAuto');if(n)n.textContent='(เลือกเอง)';showToast('ใช้หมวด '+this.value)">${categories.map(c=>`<option value="${c.code}" ${c.code===selectedCatCode?'selected':''}>${c.code} ${esc(c.name)}</option>`).join('')}</select></label><span id="catAuto" style="opacity:.7;font-size:12px"></span></div>`}
async function suggestCategory(){try{if(!current||!categories.length)return;const p=new URLSearchParams({category:current.Category||'',sub:current['Sub Category']||'',th:current['Product Name (TH)']||'',en:current['Product Name (EN)']||''});const d=await fetch('/api/category-suggest?'+p).then(r=>r.json());if(!d.code)return;selectedCatCode=d.code;const s=$('catCode');if(s)s.value=d.code;const n=$('catAuto');if(n)n.textContent=d.code==='C09'?'(⚠ เดาให้เป็นหมวดอื่น ๆ — ตรวจหมวดอีกครั้ง)':'(เดาอัตโนมัติ — เปลี่ยนได้)';const pc=$('pillCat');if(pc)pc.textContent=d.code+' '+(d.name||'');const pf=$('pillFit');if(pf&&current){const fm=current['Fitment Models']||current['Fitment Brands']||'';pf.textContent=fm?'✓ Fitment verified':'○ ไม่มี Fitment ยืนยัน';pf.className='pill '+(fm?'ok':'warn');}updateResolvePreview();}catch{}}
function selectTemplate(i){selectedTemplate=i;if(current)selectProduct(items.indexOf(current))}
function showToast(msg, ok=true){
  let t=document.getElementById('toast');
  if(!t){ t=document.createElement('div'); t.id='toast'; t.style.cssText='position:fixed;right:18px;bottom:18px;z-index:99;padding:12px 16px;border-radius:10px;font-size:13px;font-weight:600;box-shadow:0 8px 24px rgba(0,0,0,.4);transition:opacity .25s'; document.body.appendChild(t); }
  t.textContent=msg; t.style.background= ok ? '#1f7a4a' : '#8b2c2c'; t.style.color='#fff'; t.style.opacity='1';
  clearTimeout(t._hide); t._hide=setTimeout(()=> t.style.opacity='0', 1800);
}
async function copyWithFallback(text){
  const v = String(text ?? '');
  if(!v || v==='-'){ showToast('ไม่มีข้อความให้คัดลอก', false); return false; }
  try{
    if(navigator.clipboard && window.isSecureContext){
      await navigator.clipboard.writeText(v);
    } else throw new Error('no clipboard');
  }catch(e){
    try{
      const ta=document.createElement('textarea'); ta.value=v; ta.setAttribute('readonly',''); ta.style.cssText='position:fixed;left:-9999px;top:-9999px';
      document.body.appendChild(ta); ta.select(); ta.setSelectionRange(0, 99999);
      const ok=document.execCommand('copy'); document.body.removeChild(ta);
      if(!ok) throw new Error('execCommand failed');
    }catch(e2){
      showToast('คัดลอกไม่สำเร็จ: '+ (e2.message||''), false);
      // last resort: show text for manual copy
      prompt('คัดลอกด้วย Ctrl+C แล้ว Enter:', v);
      return false;
    }
  }
  return true;
}
async function copyProduct(){
  const ok=await copyWithFallback(JSON.stringify(current,null,2));
  if(ok) showToast('คัดลอกข้อมูลสินค้าแล้ว ✓');
}
async function copyText(x, btn){
  const ok=await copyWithFallback(x);
  if(!ok) return;
  showToast('คัดลอกแล้ว ✓');
  if(btn){ const orig=btn.textContent; btn.textContent='คัดลอกแล้ว ✓'; btn.disabled=true; setTimeout(()=>{btn.textContent=orig; btn.disabled=false;},1600); }
}
async function copyFlow(i, btn){
  const v = window.lastOutput?.scenes?.[i]?.flow_prompt || '';
  await copyText(v, btn);
}
async function copyField(field, btn){
  let v = window.lastOutput?.[field];
  if(Array.isArray(v)) v=v.join('\n');
  await copyText(v||'', btn);
}
async function copyPlatform(platform, btn){
  const v = window.lastOutput?.platform_captions?.[platform] || window.lastOutput?.platformCaptions?.[platform] || '';
  if(!v){ // fallback: build from caption+hashtags+cta
    const fallback = [window.lastOutput?.caption||'', (window.lastOutput?.hashtags||[]).join(' '), window.lastOutput?.cta||''].filter(Boolean).join('\n\n');
    await copyText(fallback, btn); return;
  }
  await copyText(v, btn);
}
function buildPlatformFallback(){
  const h=(window.lastOutput?.hashtags||[]).join(' ');
  const cap=window.lastOutput?.caption||''; const cta=window.lastOutput?.cta||'';
  if(!cap && !h && !cta) return null;
  return { facebook: [cap, cta, h].filter(Boolean).join('\n\n'), tiktok: [cap.split('\n')[0]||cap, h].filter(Boolean).join('\n'), instagram: [cap, h].filter(Boolean).join('\n\n'), line: [cap, cta].filter(Boolean).join('\n'), shopee: [cap, cta].filter(Boolean).join('\n') };
}
async function generate(force=false,skipGate=false){if(!current)return;const o=$('output');
 if(!skipGate&&window.lastSheet&&window.lastSheet.status!=='VERIFIED'){o.innerHTML=`<div class="qa-box qa-review">⚠ Product Sheet ยังไม่ Verified (${esc(window.lastSheet.status)}) — บางมุมอาจไม่มี reference<div style="margin-top:8px;display:flex;gap:6px;flex-wrap:wrap"><button class="secondary" onclick="openSheetDrawer()">ตรวจ Product Sheet</button><button class="generate" onclick="generate(${force},true)">สร้างต่อ</button></div></div>`;return;}o.innerHTML=`<div class="loading">${force?'กำลังตรวจใหม่และเจน Pack...':'กำลังตรวจรูปสินค้า + Source + Series แล้วสร้าง Pack...'}</div>`;genSteps();const r=await fetch('/api/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product:current,vCode:selectedV,duration:selectedDur,mode:selectedMode,flowModel:selectedFlowModel,force,categoryCode:(($('catCode')||{}).value||selectedCatCode||'')})});const d=await r.json();if(d.error){clearInterval(window._gsT);o.innerHTML=`<div class="error">${esc(d.error)}</div>`;return}if(d.raw){o.innerHTML=`<section class="result"><div class="result-head"><h2>Content Pack</h2><button class="secondary" onclick="downloadJSON()">Export JSON</button></div><pre>${esc(d.raw)}</pre><div style="margin-top:10px"><button class="secondary" onclick="copyText(document.querySelector('.result pre').textContent, this)">Copy Raw</button></div></section>`; window.lastOutput={raw:d.raw};clearInterval(window._gsT); return}window.lastOutput=d;
  afterGenerate(d);clearInterval(window._gsT);setWorkflow('do');
  const pc = d.platform_captions || d.platformCaptions || buildPlatformFallback();
  const platformOrder = [
    {key:'facebook', label:'Facebook', icon:'📘'},
    {key:'tiktok', label:'TikTok', icon:'🎵'},
    {key:'instagram', label:'Instagram', icon:'📸'},
    {key:'line', label:'LINE', icon:'💬'},
    {key:'shopee', label:'Shopee', icon:'🛒'}
  ];
  const platformHtml = pc ? `<h3>📱 แคปชั่นพร้อมโพสต์ (ก๊อปไปวางได้เลย)</h3><div class="platform-grid">${platformOrder.map(p=> pc[p.key] ? `<div class="box platform-box"><div class="box-title"><h3>${p.icon} ${p.label}</h3><button onclick="copyPlatform('${p.key}', this)">Copy</button></div><div class="out">${esc(pc[p.key])}</div></div>` : '').join('')}</div><div style="margin-top:8px"><button class="secondary" onclick="copyPlatform('facebook', this)" style="margin-right:6px">Copy Facebook ทั้งชุด</button><button class="secondary" onclick="copyText(Object.entries(pc).map(([k,v])=> '【'+k.toUpperCase()+'】\\n'+v).join('\\n\\n---\\n\\n'), this)">Copy ทั้งหมด</button></div>` : '';
  const qa=d.qa||d._meta?.qa;const qaHtml=qa?`<div class="qa-box ${qa.status==='PASS'?'qa-pass':'qa-review'}"><b>${qa.status==='PASS'?'✅ CHECK ผ่าน':'⚠️ CHECK ต้องทบทวน'}</b>${(qa.checks||[]).map(x=>`<div>${x.status==='PASS'?'✓':'✕'} ${esc(x.message)}</div>`).join('')}</div>`:'';const auditHtml=Array.isArray(d.visual_asset_audit)?`<div class="box"><div class="box-title"><h3>👁️ ตรวจรูปต้นฉบับ</h3><span class="result-sub">AI เห็น ${d._meta?.imageCount||'?'} ภาพ</span></div><div class="out">${d.visual_asset_audit.map((a,i)=>`ภาพ ${i+1}: ${esc(a.classification||'UNKNOWN')} — ${esc(a.what_is_visible||'')}\nใช้ได้: ${esc(a.allowed_use||'')}`).join('\n\n')}</div></div>`:'';o.innerHTML=`<section class="result"><div class="result-head"><div><h2>Content Pack</h2><small class="result-sub">${esc(d._meta?.model||'AI')} · ${d._meta?.cache?'ใช้ Cache ไม่เรียก AI ซ้ำ':'วิเคราะห์ภาพจริง + สร้างใหม่'}</small></div><div style="display:flex;gap:7px"><button class="secondary" onclick="generate(true)">♻️ เจนใหม่</button><button class="secondary" onclick="downloadJSON()">Export JSON</button></div></div>${qaHtml}${storyboardHtml(d)}${auditHtml}${box('Hook',d.hook,'hook')}${box('Script',d.script,'script')}${box('Voice Over',d.voiceover,'voiceover')}<h3>🎬 Scenes / Google Flow</h3>${(d.scenes||[]).map((s,i)=>`<div class="scene"><div class="scene-top"><div><b>${esc(s.time||`Scene ${i+1}`)}</b><small class="scene-ref">${esc(s.reference||'')} · Start: ${esc(s.start_source||'')}</small></div><button onclick="copyFlow(${i}, this)">Copy Flow</button></div><p>${esc(s.visual||'')}</p>${s.overlay?`<div class="overlay">Overlay: ${esc(s.overlay)}</div>`:''}<pre>${esc(s.flow_prompt||'')}</pre></div>`).join('')}${box('🧩 วิธีใช้รูปกับแต่ละ Scene',d.image_to_video_prompt,'image_to_video_prompt',false)}${box('Caption (รวม)',d.caption,'caption')}${box('CTA',d.cta,'cta')}<div class="copybar"><button class="generate" onclick="copyAllPack(this)">⧉ Copy All</button><button class="secondary" onclick="copyField('hook',this)">Copy Hook</button><button class="secondary" onclick="copyField('script',this)">Copy Script</button><button class="secondary" onclick="copyFlow(0,this)">Copy Flow 1</button></div><div class="tags">${(d.hashtags||[]).map(x=>`<span>${esc(x)}</span>`).join('')}</div>${platformHtml}${box('Source Facts',Array.isArray(d.source_facts)?d.source_facts.join('\n'):d.source_facts,'source_facts',false)}${box('Warnings',Array.isArray(d.warnings)?d.warnings.join('\n'):d.warnings,'warnings',false)}</section>`;
  renderPostGenWorkflow();
}
function box(t,v,field,open=true){const inner=`<div class="out">${esc(v||'-')}</div>`;if(open)return `<div class="box"><div class="box-title"><h3>${esc(t)}</h3><button onclick="copyField('${field}', this)">Copy</button></div>${inner}</div>`;return `<details class="out-sec"><summary>${esc(t)}</summary><div class="sec-body"><div style="margin:10px 0"><button class="secondary" onclick="copyField('${field}', this)">Copy</button></div>${inner}</div></details>`}function storyboardHtml(d){const sb=d.storyboard;if(!sb||!sb.scenes?.length)return '';const fps=d.flow_prompts||[];return `<div class="box" style="border-color:#4a5a35"><div class="box-title"><h3>🗺 Storyboard · ${sb.generations} generations · ${esc(sb.total_duration||'')} (ขอ ${esc(sb.requested||'')}) · ${esc(sb.modelLabel||sb.model||'')}</h3><button onclick="copyAllFlow(this)">Copy All Flow</button></div>`+sb.scenes.map((s,i)=>{const fp=fps[i];return `<details class="out-sec"${i===0?' open':''} style="margin-top:8px"><summary>${esc(s.id)} · ${esc(String(s.duration||''))} — ${esc(String(s.purpose||'').slice(0,60))}</summary><div class="sec-body"><div style="font-size:12px;line-height:1.8">🎯 ${esc(s.purpose||'')}<br>🖼 ${(s.reference||[]).map(esc).join(' + ')}<br>▶ เริ่ม: ${esc(s.start_source||'')} → จบ: ${esc(s.end_goal||'')}<br>🔗 ${esc(s.continuity||'')}${s.reference_status==='NEEDS_REVIEW'?' · <b style="color:#ffd76a">⚠ ไม่มี reference — ตรวจก่อน</b>':''}</div>${fp&&fp.prompt?`<div style="margin:8px 0"><button class="secondary" onclick="copyText(window.lastOutput.flow_prompts[${i}].prompt,this)">Copy Prompt</button></div><div class="out" style="white-space:pre-wrap">${esc(fp.prompt)}</div>`:''}</div></details>`}).join('')+`</div>`}
function copyAllFlow(btn){const fps=window.lastOutput?.flow_prompts||[];copyText(fps.map(f=>`[${f.scene_id} · ${f.duration}]\n${f.prompt}`).join('\n\n---\n\n'),btn);}
function downloadJSON(){const b=new Blob([JSON.stringify({product:current,template:templates[selectedTemplate],output:window.lastOutput},null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`WDI-${current['Product Code']||'product'}-content-pack.json`;a.click();URL.revokeObjectURL(a.href)}boot();

