const BADGE={NOT_STARTED:['○ ยังไม่ทำ','#8d99aa'],IN_PROGRESS:['🔵 กำลังทำ','#4aa3ff'],GENERATED:['✓ Generate แล้ว','#ffd76a'],QC_PENDING:['◐ รอ QC','#ff9f43'],QC_PASSED:['✓✓ QC ผ่าน','#2ed573'],READY_TO_PUBLISH:['🟢 พร้อมลง','#2ed573'],PUBLISHED:['🚀 ลงแล้ว','#eccc68'],REVISION_REQUIRED:['⚠ ต้องแก้','#ff6b6b'],ERROR:['✕ Error','#ff6b6b']};
const STATUS_GROUPS={NOT_STARTED:['NOT_STARTED'],DOING:['IN_PROGRESS'],DONE:['GENERATED','QC_PENDING'],QC:['QC_PENDING','REVISION_REQUIRED'],PASSED:['QC_PASSED','READY_TO_PUBLISH'],PUBLISHED:['PUBLISHED'],ERROR:['ERROR']};
let statusMap={};
async function loadDashboard(){try{const d=await fetch('/api/dashboard').then(r=>r.json());const s=d.jobs_by_status||{};const pill=(l,v)=>`<span style="background:#1c2532;border:1px solid #2a3340;border-radius:999px;padding:3px 10px;white-space:nowrap">${l}: <b>${v}</b></span>`;const el=$('dashstrip');if(el){const done=d.products_involved||0,total=d.products_total||0;const chip=(l,v)=>`<span class="q-chip">${l} <b>${v}</b></span>`;el.innerHTML=`<span class="q-title">งานวันนี้</span><span class="q-count">${done} <small>/ ${total} เริ่มแล้ว</small></span><span class="q-chips">${chip('ยังไม่ทำ',d.products_untouched)}${chip('กำลังทำ',s.IN_PROGRESS||0)}${chip('รอตรวจ',(s.GENERATED||0)+(s.QC_PENDING||0)+(s.REVISION_REQUIRED||0))}${chip('พร้อมลง',(s.QC_PASSED||0)+(s.READY_TO_PUBLISH||0))}${chip('ลงแล้ว',s.PUBLISHED||0)}</span><span class="q-next"><span class="q-suggest" id="qSuggest">กำลังหางานถัดไป...</span><button id="btnNext" onclick="startNext()">▶ งานถัดไป</button></span>`;loadNextSuggest();}}catch{}}
async function paintBadges(){try{const codes=items.map(x=>x['Product Code']).filter(Boolean);if(!codes.length)return;const m=await fetch('/api/jobs/status',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({codes})}).then(r=>r.json());statusMap={...statusMap,...m};const btns=[...document.querySelectorAll('#products .item:not(.load-more)')];btns.forEach((b,i)=>{const code=items[i]?.['Product Code'];if(!code)return;const info=m[code]||{};const st=info.state||'NOT_STARTED';const[t,c]=BADGE[st]||BADGE.NOT_STARTED;let s=b.querySelector('.stbadge');if(!s){s=document.createElement('span');s.className='stbadge';s.style.cssText='font-size:11px;margin-left:6px;white-space:nowrap';b.appendChild(s);}s.textContent=t;s.style.color=c;b.dataset.st=st;const vp=b.querySelector('[data-vp]');if(vp){const vd=info.v_done||[];vp.innerHTML=vd.length?`✓ <b>${vd.length}/${seriesV.length||15}</b> แนว (${vd.slice(0,4).join('·')}${vd.length>4?` +${vd.length-4}`:''})`:'○ ยังไม่เริ่มแนวคลิป';}});}catch{}}
function trackSelect(){try{if(!current)return;fetch('/api/track/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({productCode:current['Product Code'],vCode:selectedV,categoryCode:(($('catCode')||{}).value||selectedCatCode||''),sCode:(autoS||{}).sCode||''})}).catch(()=>{});}catch{}}
async function loadVMatrix(){const el=$('vmatrix');if(!el||!current)return;try{const d=await fetch('/api/job?code='+encodeURIComponent(current['Product Code']||'')).then(r=>r.json());const done={};(d.jobs||[]).forEach(j=>{done[j.v_code]=j;});const list=seriesV.length?seriesV.map(v=>v.code):[];el.innerHTML=`<div style="font-size:12px;opacity:.75;margin:8px 0 4px">🗂 Content Matrix (จากฐานข้อมูล — แตะเพื่อเลือก V):</div><div style="display:flex;gap:4px;flex-wrap:wrap">${list.map(v=>{const j=done[v];return `<button class="secondary" style="font-size:11px;padding:3px 7px;${j?'border-color:#2ed573':''}" onclick="setV('${v}')" title="${j?`ทำแล้ว ${j.s_code} v${j.current_version} (${j.status})`:'ยังไม่ทำ — แตะเพื่อสร้าง'}">${j?'✓':'○'} ${v}</button>`}).join('')}</div>`;}catch{}}
async function afterGenerate(d){try{const m=d._meta||{};if(m.jobId)window.lastJobId=m.jobId;loadDashboard();paintBadges();loadVMatrix();const jid=window.lastJobId;if(!jid)return;const pub=await fetch('/api/publish?job='+jid).then(r=>r.json()).catch(()=>null);const o=$('output');const sec=o?.querySelector('.result');if(!sec)return;if(sec.querySelector('.trackbox'))return;const plats=[['facebook','FB'],['instagram','IG'],['line','LINE'],['tiktok','TikTok']];const box=document.createElement('div');box.className='box trackbox';box.innerHTML=`<div class="box-title"><h3>🗂 Tracking ${m.mappedS?`(AUTO ${m.mappedS})`:''} ${m.version?`v${m.version}`:''} ${m.cache?'(cache)':''}</h3></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:8px"><button class="secondary" onclick="qcVote(true)">✅ QC ผ่าน</button><button class="secondary" onclick="qcVote(false)">⚠ QC ไม่ผ่าน</button></div>${m.sheetWarn?`<div class="qa-box qa-review" style="margin:0 0 8px">⚠ ${esc(m.sheetWarn)}</div>`:''}<div style="display:flex;gap:6px;flex-wrap:wrap">${plats.map(([k,l])=>`<button class="secondary" data-pub="${k}" onclick="pubToggle('${k}')">${((pub||{})[k+'_status']==='PUBLISHED')?'🚀':'○'} ${l}</button>`).join('')}</div>`;sec.prepend(box);}catch{}}
async function qcVote(pass){try{if(!window.lastJobId)return showToast('ไม่มี job',false);await fetch('/api/qc',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jobId:window.lastJobId,passed:pass})});showToast(pass?'QC ผ่าน ✓✓':'ส่งกลับแก้ ⚠');loadDashboard();paintBadges();loadVMatrix();}catch(e){showToast('QC ไม่สำเร็จ',false)}}
async function pubToggle(k){try{if(!window.lastJobId)return;const cur=document.querySelector(`[data-pub="${k}"]`)?.textContent||'';const to=!cur.includes('🚀');await fetch('/api/publish',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({jobId:window.lastJobId,platform:k,status:to?'PUBLISHED':'PENDING'})});afterGenerate(window.lastOutput||{});}catch{}}
async function askAssistant(){const qi=$('assistantQ');const q=qi?.value||'';if(!q.trim())return;const a=$('assistantAns');if(a)a.textContent='กำลังถามฐานข้อมูล...';try{const d=await fetch('/api/assistant',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question:q})}).then(r=>r.json());if(a)a.textContent=(d.answer||'(ไม่มีคำตอบ)')+((d.sources||[]).length?'\n\n— อ้างอิง: '+d.sources.join(', '):'');}catch(e){if(a)a.textContent='ถามไม่สำเร็จ: '+(e.message||'');}}
