function openTruth(){try{if(!current)return;const rows=[['รหัส',current['Product Code']],['ชื่อ (TH)',current['Product Name (TH)']],['ชื่อ (EN)',current['Product Name (EN)']],['หมวด',current.Category],['หมวดย่อย',current['Sub Category']],['รายละเอียด',current['Description (TH)']],['Description',current['Description (EN)']],['Fitment Brands',current['Fitment Brands']],['Fitment Models',current['Fitment Models']],['Fitment Contexts',current['Fitment Contexts']],['Fitment Evidence',current['Fitment Evidence']],['Car Brand',current['Car Brand']],['Car Model',current['Car Model']],['Source',current['Product URL']],['Main Image',current['Main Image URL']],['Additional',current['Additional Images']]];const tb=$('truthBody');if(tb)tb.innerHTML='<table>'+rows.filter(([,v])=>String(v||'').trim()).map(([k,v])=>k==='Source'&&String(v||'').trim()?`<tr><td>${esc(k)}</td><td><a target="_blank" href="${esc(v)}" rel="noopener"><button class="secondary" style="margin-bottom:6px">เข้าดูตัวเว็บ ↗</button></a><br><small style="opacity:.6;word-break:break-all">${esc(v)}</small></td></tr>`:`<tr><td>${esc(k)}</td><td>${esc(v)}</td></tr>`).join('')+'</table>';const m=$('truthModal');if(m)m.classList.add('on');}catch{}}
function closeTruth(){const m=$('truthModal');if(m)m.classList.remove('on');}
async function loadSheetBox(){const el=$('sheetBox');if(!el||!current)return;try{
 const p=new URLSearchParams({code:current['Product Code']||'',cat:(($('catCode')||{}).value||selectedCatCode||''),th:current['Product Name (TH)']||'',en:current['Product Name (EN)']||'',url:current['Product URL']||'',img:current['Main Image URL']||'',imgs:current['Additional Images']||'',fb:current['Fitment Brands']||'',fm:current['Fitment Models']||'',fc:current['Fitment Contexts']||'',dth:current['Description (TH)']||'',den:current['Description (EN)']||''});
 const d=await fetch('/api/sheet?'+p).then(r=>r.json());if(d.error)throw new Error(d.error);
 const s=d.summary;window.lastSheet=s;
 const stColor=s.status==='VERIFIED'?'#2ed573':(s.status==='NEEDS_REVIEW'?'#ffd76a':'#8d99aa');
 el.innerHTML=`<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><b>PRODUCT IDENTITY</b><span class="pill" style="border-color:${stColor};color:${stColor}">${esc(s.status)} · v${s.version} · ${s.confidence}%</span></div>
 <div class="keyfacts" style="margin:8px 0"><li>✓ Visual: shape/color/material → ดูภาพอ้างอิง (${s.counts.references} ภาพ)</li><li>✓ Components: ${s.counts.components_verified}/${s.counts.components_total} verified</li><li>✓ Negative Lock: ${s.counts.negative_locks} ข้อ</li></div>
 <div style="display:flex;gap:6px;flex-wrap:wrap"><button class="secondary" onclick="openSheetDrawer()">ดู Product Sheet</button>${s.status!=='VERIFIED'?'<button class="secondary" onclick="verifySheet()">ยืนยัน Sheet ✓</button>':''}</div>`;
}catch(e){el.innerHTML=`<div class="empty-state" style="padding:10px">สร้าง Sheet ไม่สำเร็จ: ${esc(e.message||'')}</div>`;}}
async function openSheetDrawer(){try{
 if(!current)return;const m=$('sheetModal');const tb=$('sheetBody');if(!m||!tb)return;
 tb.innerHTML='กำลังโหลด...';m.classList.add('on');
 const d=await fetch('/api/sheet/detail?code='+encodeURIComponent(current['Product Code']||'')).then(r=>r.json());
 if(d.error)throw new Error(d.error);
 const sec=(t,obj)=>{const ks=Object.keys(obj||{});if(!ks.length)return '';return `<h4 style="margin:12px 0 6px">${t}</h4><table>`+ks.map(k=>{const v=obj[k];const txt=(v&&typeof v==='object')?(v.value||''):(v||'');const ev=(v&&typeof v==='object'&&v.evidence)?` <small style="opacity:.6">[${esc(v.evidence)}]</small>`:'';return `<tr><td>${esc((v&&v.label)||k)}</td><td>${esc(txt)}${ev}</td></tr>`}).join('')+'</table>';};
 tb.innerHTML=`<div><b>Sheet #${d.sheet.id} v${d.sheet.version}</b> <span class="pill">${esc(d.sheet.status)} · ${d.sheet.confidence}%</span></div>`
 +sec('Identity',d.identity.identity)+sec('Fitment',d.identity.fitment)+sec('Components',d.identity.components)
 +`<h4 style="margin:12px 0 6px">References (${(d.references||[]).length})</h4>`+((d.references||[]).map(r=>`<div style="font-size:12px;margin-bottom:4px"><b>${esc(r.view_type)}</b> · ${esc(r.image_url)}</div>`).join('')||'<small>ไม่มี</small>')
 +sec('Identity Lock',d.locks)+sec('Video Constraints',(d.locks||{}).video_constraints)
 +`<h4 style="margin:12px 0 6px">Versions</h4><div id="sheetVers" style="font-size:12px">กำลังโหลด...</div>`
 +`<div style="margin-top:10px;display:flex;gap:6px">${d.sheet.status!=='VERIFIED'?'<button class="secondary" onclick="verifySheet()">ยืนยัน Sheet ✓</button>':''}</div>`;
 try{const vs=await fetch('/api/sheet/versions?code='+encodeURIComponent(current['Product Code']||'')).then(r=>r.json());const ve=$('sheetVers');if(ve)ve.innerHTML=(vs||[]).map(v=>`v${v.version_number} · ${esc(v.status)} · ${v.created_at||''}${v.is_current?' · <b>current</b>':''}`).join('<br>')||'—';}catch{}
}catch(e){const tb=$('sheetBody');if(tb)tb.textContent='โหลดไม่สำเร็จ: '+(e.message||'');}}
function closeSheet(){const m=$('sheetModal');if(m)m.classList.remove('on');}
