async function sheetImageStudio(){if(!current)return;const o=$('output');o.innerHTML='<div class="loading">AI กำลังอ่านภาพอ้างอิง WDI + เขียน Product Sheet Prompt... (60-90 วิ)</div>';try{
 const r=await fetch('/api/sheet-prompt',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({product:current,categoryCode:(($('catCode')||{}).value||selectedCatCode||'')})}).then(r=>r.json());
 if(r.error||!r.prompt)throw new Error(r.error||'สร้าง prompt ไม่สำเร็จ');
 window._sheetPrompt=r.prompt;
 const us=[current['Main Image URL']].concat(String(current['Additional Images']||'').split(';')).map(s=>String(s||'').trim()).filter((v,i,a)=>v&&a.indexOf(v)===i).slice(0,6);
 const refs=us.map(u=>`<img loading="lazy" src="${esc(imageUrl(u))}" style="width:72px;height:72px;object-fit:cover;border-radius:9px;border:1px solid #2b3441;background:#fff">`).join('');
 o.innerHTML=`<section class="result"><div class="result-head"><div><h2>🪪 Product Sheet Prompt (AI)</h2><small class="result-sub">${esc(r.model||'AI')} · อ่านภาพจริง ${r.imageCount||us.length} ภาพ${r.sheet?` · Sheet #${r.sheet.id} v${r.sheet.version} ${r.sheet.status}`:''}</small></div><div style="display:flex;gap:7px"><button class="secondary" onclick="copyText(window._sheetPrompt,this)">Copy</button></div></div>${refs?`<div style="display:flex;gap:6px;flex-wrap:wrap;margin:10px 0">${refs}</div>`:''}<div class="box"><div class="box-title"><h3>Prompt</h3></div><div class="out" style="white-space:pre-wrap;max-height:420px;overflow:auto">${esc(r.prompt)}</div></div><div style="display:flex;gap:6px;flex-wrap:wrap;margin-top:10px"><button class="secondary" onclick="genSheetImageWH(1024,1280,this)">สร้างภาพ 4:5</button><button class="secondary" onclick="genSheetImageWH(1024,1024,this)">สร้างภาพ 1:1</button></div><div id="sheetShotImg" style="margin-top:8px"></div></section>`;
 setWorkflow('do');
}catch(e){o.innerHTML=`<div class="error">${esc(e.message||'')}</div>`;}}
async function genSheetImageWH(w,h,btn){try{if(!window._sheetPrompt)return showToast('ยังไม่มี prompt',false);const box=$('sheetShotImg');if(box)box.innerHTML='<div class="loading">กำลังสร้างภาพตัวอย่าง...</div>';if(btn)btn.disabled=true;const r=await fetch('/api/image-generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:window._sheetPrompt,w,h,mode:w===h?'detail':'hero'})}).then(r=>r.json());if(!r.ok)throw new Error(r.error||'สร้างภาพไม่สำเร็จ');if(box)box.innerHTML=`<img src="data:${r.mime||'image/jpeg'};base64,${r.data}" alt="sheet preview" style="max-width:100%;border-radius:12px;border:1px solid #303846">`;}catch(e){const box=$('sheetShotImg');if(box)box.innerHTML=`<div class="error">${esc(e.message||'')}</div>`;}finally{if(btn)btn.disabled=false;}}
async function verifySheet(){try{if(!current)return;const r=await fetch('/api/sheet/verify',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code:current['Product Code']})}).then(r=>r.json());if(r.error)throw new Error(r.error);showToast('Sheet VERIFIED ✓');loadSheetBox();if($('sheetModal')?.classList.contains('on'))openSheetDrawer();}catch(e){showToast('ยืนยันไม่สำเร็จ',false);}}
const STATUS_CHIPS=[['','ทั้งหมด'],['NOT_STARTED','○ ยังไม่ทำ'],['DOING','🔵 กำลังทำ'],['DONE','✓ ทำแล้ว'],['QC','◐ QC'],['PASSED','✓✓ ผ่าน/พร้อม'],['PUBLISHED','🚀 ลงแล้ว'],['ERROR','✕ ปัญหา']];
function renderStatusChips(){const el=$('statusChips');if(!el)return;const cur=$('statusFilter')?.value||'';el.innerHTML=STATUS_CHIPS.map(([v,l])=>`<button class="schip${v===cur?' on':''}" onclick="setStatusFilter('${v}')">${l}</button>`).join('')+`<select id="sortMode" aria-label="เรียงลำดับ" onchange="sortItems(this.value)" style="font-size:11px;border:1px solid #303846;background:#131a24;color:#cfd7e2;border-radius:999px;padding:5px 8px"><option value="">เรียง: เริ่มต้น</option><option value="todo"${window._sortMode==='todo'?' selected':''}>ยังไม่ทำก่อน</option><option value="done"${window._sortMode==='done'?' selected':''}>ทำแล้วก่อน</option></select>`}
function sortItems(mode){window._sortMode=mode||'';if(!mode||!items.length){renderProductList();return;}const rank=s=>({NOT_STARTED:0,IN_PROGRESS:1,GENERATED:2,QC_PENDING:2,REVISION_REQUIRED:3,QC_PASSED:4,READY_TO_PUBLISH:4,PUBLISHED:5,ERROR:6}[s]??0);items=[...items].sort((a,b)=>{const ra=rank(((statusMap[a['Product Code']]||{}).state)||'NOT_STARTED'),rb=rank(((statusMap[b['Product Code']]||{}).state)||'NOT_STARTED');return mode==='done'?rb-ra:ra-rb;});renderProductList();}
function setStatusFilter(v){const s=$('statusFilter');if(s)s.value=v;renderStatusChips();loadProducts();}
function renderQprompts(){const el=$('qprompts');if(!el)return;const qs=['วันนี้ทำถึงไหนแล้ว','งานถัดไปคืออะไร','V04 ทำไปแล้วกี่ตัว','ตัวไหนรอตรวจ','ตัวไหนยังไม่ทำ'];el.innerHTML=qs.map(q=>`<button onclick="askPreset('${q}')">${q}</button>`).join('')}
function askPreset(q){const i=$('assistantQ');if(i)i.value=q;const p=$('assistantPanel');if(p&&!p.classList.contains('open'))toggleAssistant();askAssistant();}
async function loadNextSuggest(){try{const n=await fetch('/api/next?limit=1').then(r=>r.json());const el=$('qSuggest');if(el)el.textContent=n.length?`ถัดไป: ${n[0].product_code} (${n[0].product_name_th||n[0].product_name_en||''})`:'ไม่มีงานเหลือแล้ว';}catch{}}
async function startNext(){try{const n=await fetch('/api/next?limit=1').then(r=>r.json());if(!n.length)return showToast('ไม่มีงานเหลือแล้ว',false);const code=n[0].product_code;$('search').value=code;await loadProducts();const btn=document.querySelector('#products .item:not(.load-more)');if(btn&&items.length)selectProduct(0,btn);showToast('งานถัดไป: '+code);}catch(e){showToast('โหลดงานถัดไปไม่สำเร็จ',false)}}
