const SHEET_SIZES=[{k:'hero',label:'Hero 4:5',w:1024,h:1280,frame:'สินค้าเด่นกลางภาพ พื้นที่ว่างด้านบนสำหรับข้อความ'},{k:'detail',label:'Detail 1:1',w:1024,h:1024,frame:'มาโครจุดเด่น 2-3 จุดที่ยืนยันแล้ว'},{k:'story',label:'Story 9:16',w:768,h:1344,frame:'แนวตั้งเต็มจอสำหรับ Reels/TikTok เว้น safe area บน-ล่าง'},{k:'cover',label:'Cover 16:9',w:1344,h:768,frame:'แนวนอนสำหรับปก/แบนเนอร์ สินค้าอยู่ขวา เว้นที่ซ้าย'}];
async function sheetImageStudioLegacy(){if(!current)return;const o=$('output');o.innerHTML='<div class="loading">กำลังดึง Product Sheet + ประกอบ Image Prompts...</div>';try{
 const code=current['Product Code']||'';
 let d=window._sheetDetail;
 if(!d||d.code!==code){d=await fetch('/api/sheet/detail?code='+encodeURIComponent(code)).then(r=>r.json());if(d.error)throw new Error(d.error);window._sheetDetail={code,...d};}
 const idn=d.identity||{};const info=idn.identity||{};const comps=idn.components||{};
 const vok=Object.entries(comps).filter(([,c])=>c&&c.status==='VERIFIED').map(([,c])=>`${c.label||''}: ${c.value||''}`);
 const locks=d.locks||{};
 const base=`DIAMOND automotive product photo of ${info.product_code||code} ${info.product_name||''} ${info.product_name_en||''} (${info.category||''}). Use attached WDI reference images as the exact visual source of truth. Preserve exactly: ${(vok.length?vok.join(' | '):'silhouette, proportions, color, finish as visible in reference')}. ${(locks.negative_lock||[]).slice(0,4).join(' ')} Premium studio lighting, clean dark background, photorealistic, no text, no logo redraw, no QR.`;
 window._sheetShots=SHEET_SIZES.map(s=>({...s,prompt:`${base} Framing (${s.label} ${s.w}x${s.h}): ${s.frame}.`}));
 const refs=(d.references||[]).map(r=>`<img loading="lazy" src="${esc(imageUrl(r.image_url))}" title="${esc(r.view_type||'')}" style="width:72px;height:72px;object-fit:cover;border-radius:9px;border:1px solid #2b3441;background:#fff">`).join('');
 o.innerHTML=`<section class="result"><div class="result-head"><div><h2>🪪 Product Sheet Image Prompts</h2><small class="result-sub">Sheet #${d.sheet.id} v${d.sheet.version} · ${esc(d.sheet.status)} · อ้างอิงภาพ WDI ${d.references?.length||0} ภาพ</small></div></div>${refs?`<div style="display:flex;gap:6px;flex-wrap:wrap;margin:10px 0">${refs}</div>`:''}${window._sheetShots.map((s,i)=>`<div class="box"><div class="box-title"><h3>${s.label} · ${s.w}×${s.h}</h3><span><button class="secondary" onclick="copyText(window._sheetShots[${i}].prompt,this)">Copy</button> <button class="secondary" onclick="genSheetImage(${i},this)">สร้างภาพ</button></span></div><div class="out" style="white-space:pre-wrap">${esc(s.prompt)}</div><div id="sheetShot${i}" style="margin-top:8px"></div></div>`).join('')}</section>`;
}catch(e){o.innerHTML=`<div class="error">สร้างไม่สำเร็จ: ${esc(e.message||'')}</div>`;}}
async function genSheetImageLegacy(i,btn){try{const s=(window._sheetShots||[])[i];if(!s)return;const box=$('sheetShot'+i);if(box)box.innerHTML='<div class="loading">กำลังสร้างภาพตัวอย่าง...</div>';if(btn){btn.disabled=true;}const r=await fetch('/api/image-generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:s.prompt,w:s.w,h:s.h,mode:s.k})}).then(r=>r.json());if(!r.ok)throw new Error(r.error||'สร้างภาพไม่สำเร็จ');if(box)box.innerHTML=`<img src="data:${r.mime||'image/jpeg'};base64,${r.data}" alt="${esc(s.label)}" style="max-width:100%;border-radius:12px;border:1px solid #303846">`;}catch(e){const box=$('sheetShot'+i);if(box)box.innerHTML=`<div class="error">${esc(e.message||'')}</div>`;}finally{if(btn)btn.disabled=false;}}
function thumbsHtml(p){try{const main=String(p['Main Image URL']||'').trim();const us=String(p['Additional Images']||'').split(';').map(s=>s.trim()).filter(u=>u&&u!==main).filter((v,i,a)=>a.indexOf(v)===i).slice(0,5);if(!us.length)return '';return us.map(u=>`<img loading="lazy" src="${esc(imageUrl(u))}" onclick="swapImg(this)" title="ดูภาพนี้" alt="ภาพเพิ่มเติม">`).join('');}catch{return ''}}
function swapImg(el){try{const m=document.querySelector('#detail .product-img');if(m&&el&&el.src)m.src=el.src;}catch{}}
function keyFactsHtml(p){try{const lis=[];const fit=p['Fitment Models']||p['Fitment Brands']||'';lis.push(fit?`✓ Fitment: ${esc(String(fit).slice(0,80))}`:'○ ยังไม่มี Fitment ยืนยัน');const cat=[p.Category,p['Sub Category']].filter(Boolean).join(' / ');if(cat)lis.push(`หมวด: ${esc(cat)}`);const imgs=[p['Main Image URL']].concat(String(p['Additional Images']||'').split(';')).map(s=>String(s||'').trim()).filter((v,i,a)=>v&&a.indexOf(v)===i);if(imgs.length)lis.push(`ภาพสินค้า: ${imgs.length} ภาพ`);return lis.slice(0,4).map(x=>`<li>${x}</li>`).join('');}catch{return ''}}
const GEN_STEPS=['✓ อ่านข้อมูลสินค้า','✓ ตรวจ Product Truth','✓ เลือก Production Template','● กำลังสร้าง Content…','○ เตรียมผลลัพธ์'];
function genSteps(){try{let i=0;clearInterval(window._gsT);window._gsT=setInterval(()=>{const o=document.querySelector('#output .loading');if(!o){clearInterval(window._gsT);return;}i=Math.min(i+1,GEN_STEPS.length-1);o.innerHTML='<span>'+GEN_STEPS.slice(0,i+1).join('<br>')+'</span>';},9000);}catch{}}
async function generateMarketplace(){if(!current)return;const o=$('output');const d=buildLocalMarketplace(current);window.lastMarketplace=d;const names=[['hero','Hero 4:5'],['detail','Detail 1:1'],['context','Context 4:5'],['catalog','Catalog 4:5'],['social','Social 4:5']];const all=()=>names.map(([k,l])=>'### '+l+'\n'+(window.lastMarketplace.prompts?.[k]||'')).join('\n\n')+'\n\n### Negative Prompt\n'+(window.lastMarketplace.negative_prompt||'');const cards=names.map(([k,l])=>marketCard(k,l,d.prompts?.[k])).join('');o.innerHTML=`<section class="result"><div class="result-head"><div><h2>Marketplace Prompts · DIAMOND Pro</h2><small class="result-sub">Universal image prompt pack · WDI Fitment-aware · พร้อม Copy / Download / Share</small></div><button class="secondary" onclick="enhanceMarketplace(this)">AI Enhance</button></div><div class="prompt-toolbar"><button class="generate" onclick="copyText(window.lastMarketplace.prompts.hero,this)">Copy Hero</button><button class="secondary" onclick="copyText(window.lastMarketplace.prompts.context,this)">Copy Context</button><button class="secondary" onclick="copyText(window._marketplaceAll(),this)">Copy All</button><button class="secondary" onclick="downloadMarketplacePrompts()">Download .txt</button></div>${cards}<div class="box"><div class="box-title"><h3>Negative Prompt</h3><button onclick="copyText(window.lastMarketplace.negative_prompt,this)">Copy</button></div><div class="out">${esc(d.negative_prompt||'')}</div></div><div class="box"><div class="box-title"><h3>Source / Fitment Facts</h3><button onclick="copyText(window.lastMarketplace.source_facts||'',this)">Copy</button></div><div class="out">${esc(d.source_facts||'-')}</div></div></section>`;window._marketplaceAll=all;showToast('Marketplace Pro Prompt Pack พร้อมใช้ ✓');}
